-- Disposable accounts, rolled back. Run as project postgres; RPC access also checked under authenticated.
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();root_id bigint;reply_id bigint;req uuid:=gen_random_uuid();j jsonb;session jsonb;answers jsonb;n bigint;rid uuid;
begin
 insert into auth.users(id,email,role,aud,email_confirmed_at) values(a,'qa-'||a||'@example.invalid','authenticated','authenticated',now()),(b,'qa-'||b||'@example.invalid','authenticated','authenticated',now()),(c,'qa-'||c||'@example.invalid','authenticated','authenticated',now());
 insert into public.profiles(player_id,handle,display_name) values(a,'qa_'||left(replace(a::text,'-',''),12),'QA Alpha'),(b,'qa_'||left(replace(b::text,'-',''),12),'QA Beta'),(c,'qa_'||left(replace(c::text,'-',''),12),'QA Gamma');
 perform set_config('request.jwt.claim.sub',a::text,true);
 session:=public.pp_start_game('quick-math');select jsonb_agg((x->>'a')::int+(x->>'b')::int) into answers from jsonb_array_elements(session->'challenge') x;req:=gen_random_uuid();perform public.pp_submit_score((session->>'sessionId')::uuid,req,jsonb_build_object('answers',answers));perform public.pp_submit_score((session->>'sessionId')::uuid,req,jsonb_build_object('answers',answers));if (select count(*) from pp_private.player_badges where player_id=a and badge in ('first-round','perfect-five'))<>2 then raise exception 'server badges missing';end if;req:=gen_random_uuid();
 j:=public.pp_settings(a,'get');if (j->>'show_presence')::boolean or not (j->>'allow_invites')::boolean then raise exception 'unsafe defaults';end if;
 begin perform public.pp_settings(b,'get');raise exception 'foreign settings accepted';exception when raise_exception then if sqlerrm<>'PLAYER_CHANGED' then raise;end if;end;
 begin perform public.pp_moderation(a,'list');raise exception 'unprivileged moderation';exception when raise_exception then if sqlerrm<>'MODERATOR_REQUIRED' then raise;end if;end;
 perform public.pp_settings(a,'save',false,true,false);perform public.pp_settings(a,'heartbeat',p_game=>'nocna-portiernia');
 if jsonb_array_length(public.pp_settings(a,'friends'))<>0 then raise exception 'stranger presence exposed';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if jsonb_array_length(public.pp_badges(a))<>0 then raise exception 'hidden badges exposed';end if;
 begin perform public.pp_friends(b,'send',p_target=>a,p_request=>gen_random_uuid());raise exception 'disabled invites accepted';exception when raise_exception then if sqlerrm<>'INVITES_DISABLED' then raise;end if;end;
 insert into pp_private.friendships(low_id,high_id,sender_id,state) values(least(a,b),greatest(a,b),a,'accepted');
 j:=public.pp_settings(b,'friends');if jsonb_array_length(j)<>1 or j->0->>'game'<>'nocna-portiernia' then raise exception 'friend presence missing';end if;
 update pp_private.player_settings set last_seen=now()-interval '100 seconds' where player_id=a;
 if jsonb_array_length(public.pp_settings(b,'friends'))<>0 then raise exception 'stale presence exposed';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.pp_settings(a,'heartbeat',p_game=>'quick-math');
 insert into pp_private.player_blocks(blocker_id,blocked_id) values(a,b);
 perform set_config('request.jwt.claim.sub',b::text,true);if jsonb_array_length(public.pp_settings(b,'friends'))<>0 then raise exception 'blocked presence visible';end if;
 delete from pp_private.player_blocks where blocker_id=a and blocked_id=b;
 perform set_config('request.jwt.claim.sub',a::text,true);
 j:=public.pp_game_feedback_write(a,'nocna-portiernia','comment',p_body=>'Root',p_request=>gen_random_uuid());root_id:=(j->>'id')::bigint;
 perform set_config('request.jwt.claim.sub',b::text,true);
 j:=public.pp_comment_thread(b,'nocna-portiernia',root_id,'post','Reply',req);reply_id:=(j->>'id')::bigint;
 if public.pp_comment_thread(b,'nocna-portiernia',root_id,'post','Reply',req)<>j then raise exception 'retry duplicated reply';end if;
 if jsonb_array_length(public.pp_comment_thread(b,'nocna-portiernia',root_id,'read'))<>1 then raise exception 'reply unreadable';end if;
 if public.pp_comment_thread(b,'nocna-portiernia',root_id,'root')->>'body'<>'Root' then raise exception 'deep link unavailable';end if;
 begin perform public.pp_comment_thread(b,'nocna-portiernia',root_id,'post','Other',req);raise exception 'conflicting retry accepted';exception when raise_exception then if sqlerrm<>'DUPLICATE_CONFLICT' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);j:=public.pp_notifications(a,'list');if (j->>'unread')::int<>1 then raise exception 'reply notification missing';end if;n:=(j->'rows'->0->>'id')::bigint;
 perform set_config('request.jwt.claim.sub',c::text,true);begin perform public.pp_notifications(c,'read',n);raise exception 'foreign read accepted';exception when raise_exception then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);if (public.pp_notifications(a,'list')->>'unread')::int<>1 then raise exception 'foreign read changed notification';end if;
 insert into pp_private.player_blocks(blocker_id,blocked_id) values(a,b);
 if (public.pp_notifications(a,'list')->>'unread')::int<>0 then raise exception 'blocked notification visible';end if;
 delete from pp_private.player_blocks where blocker_id=a and blocked_id=b;
 perform public.pp_notifications(a,'read',n);if (public.pp_notifications(a,'list')->>'unread')::int<>0 then raise exception 'read notification persists';end if;
 if not exists(select 1 from jsonb_array_elements(public.pp_badges(a)) x where x->>'badge'='first-friend') then raise exception 'earned badge missing';end if;
 insert into pp_private.moderators values(c);perform set_config('request.jwt.claim.sub',c::text,true);
 perform public.pp_moderation(c,'list');perform public.pp_moderation(c,'account',p_handle=>(select handle from public.profiles where player_id=a));
 perform public.pp_moderation(c,'hide_comment',p_comment=>reply_id);
 if jsonb_array_length(public.pp_comment_thread(c,'nocna-portiernia',root_id,'read'))<>0 then raise exception 'hidden reply visible';end if;
 perform public.pp_moderation(c,'restore_comment',p_comment=>reply_id);
 if jsonb_array_length(public.pp_comment_thread(c,'nocna-portiernia',root_id,'read'))<>1 then raise exception 'restored reply absent';end if;
 perform public.pp_moderation(c,'ban',p_target=>b,p_days=>1);
 perform set_config('request.jwt.claim.sub',b::text,true);
 begin perform public.pp_settings(b,'get');raise exception 'banned player accepted';exception when raise_exception then if sqlerrm<>'PROFILE_REQUIRED' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',c::text,true);perform public.pp_moderation(c,'unban',p_target=>b);
 begin perform public.pp_moderation(c,'ban',p_target=>c,p_days=>1);raise exception 'self suspension accepted';exception when raise_exception then if sqlerrm<>'PROTECTED_ACCOUNT' then raise;end if;end;
 if (select count(*) from pp_private.moderation_audit where actor_id=c)<>4 then raise exception 'audit missing';end if;
 if has_table_privilege('authenticated','pp_private.player_badges','INSERT') or has_table_privilege('authenticated','pp_private.moderators','INSERT') or has_table_privilege('anon','pp_private.reply_notifications','SELECT') then raise exception 'direct privilege leak';end if;
 perform set_config('qa.owner',a::text,true);
end $$;
set local role authenticated;
do $$ declare a uuid:=current_setting('qa.owner')::uuid;begin
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.pp_settings(a,'get');perform public.pp_settings(a,'friends');perform public.pp_badges(a);perform public.pp_notifications(a,'list');
 begin perform public.pp_moderation(a,'list');raise exception 'moderation role bypass';exception when raise_exception then if sqlerrm<>'MODERATOR_REQUIRED' then raise;end if;end;
end $$;
reset role;
rollback;
